function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[el.dataset.icon]||icons.info}</svg>`)}paintIcons();window.refreshMarketSupply=()=>{if(model)renderMetrics()};
const genesis=Date.UTC(2009,0,3),day=86400000;
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:v<1?3:0}).format(v);
const compact=v=>v>=1e6?'$'+(v/1e6).toFixed(2)+'M':v>=1000?'$'+(v/1000).toFixed(v>=10000?1:2)+'k':v>=1?'$'+v.toFixed(v<10?1:0):'$'+v.toFixed(2);
const dateLabel=t=>new Date(t).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const state={view:'overview',range:'all',scale:'log',real:false,band:1,bandMode:'envelope',year:2030,showPrice:true,showTrend:true,showBands:true};
let data,points=[],model,quote=null,chartMeta,refreshing=false;
const mainView={from:null,to:null,selected:null,hovered:null};
function fitPowerLaw(items){const xs=items.map(p=>Math.log10((p.t-genesis)/day)),ys=items.map(p=>Math.log10(p.p)),n=items.length,mx=xs.reduce((a,b)=>a+b,0)/n,my=ys.reduce((a,b)=>a+b,0)/n;let xx=0,xy=0,yy=0;for(let i=0;i<n;i++){xx+=(xs[i]-mx)**2;xy+=(xs[i]-mx)*(ys[i]-my);yy+=(ys[i]-my)**2;}const b=xy/xx,a=my-b*mx;const sse=xs.reduce((s,x,i)=>s+(ys[i]-a-b*x)**2,0);return{a,b,r2:1-sse/yy,sigma:Math.sqrt(sse/(n-2)),price:t=>10**(a+b*Math.log10(Math.max(1,(t-genesis)/day)))}}
function hydrate(){let high=0;points=data.prices.map(([d,p])=>{high=Math.max(high,p);return{d,p,t:Date.parse(d+'T00:00:00Z'),dd:100*(p/high-1)}});model=fitPowerLaw(points);calibrateEnvelope();render();}
function calibrateEnvelope(){
 let record=0;const peaks=[];
 for(let i=0;i<points.length;i++){const p=points[i];if(p.p<=record)continue;let highest=true;for(let j=Math.max(0,i-365);j<=Math.min(points.length-1,i+365);j++){if(points[j].p>p.p){highest=false;break;}}if(highest){peaks.push(p);record=p.p;}}
 const peakFit=peaks.length>=2?fitPowerLaw(peaks):model;
 let topShift=-Infinity,bottomShift=Infinity;
 for(const p of points){topShift=Math.max(topShift,Math.log10(p.p/peakFit.price(p.t)));bottomShift=Math.min(bottomShift,Math.log10(p.p/model.price(p.t)));}
 model.upper=t=>Math.max(model.price(t),peakFit.price(t)*10**(topShift+.005));model.lower=t=>model.price(t)*10**(bottomShift-.005);
 model.peakCount=peaks.length;updateCoverage();
}
function bandValue(t,upper){return state.bandMode==='envelope'?(upper?model.upper(t):model.lower(t)):model.price(t)*10**((upper?1:-1)*model.sigma*state.band)}
function updateCoverage(){if(!model)return;const inside=points.filter(p=>p.p>=bandValue(p.t,false)&&p.p<=bandValue(p.t,true)).length;$('envelope-coverage').textContent=`${(inside/points.length*100).toFixed(1)}% of ${points.length.toLocaleString()} daily observations inside. ${state.bandMode==='envelope'?'Calibrated to include historical peaks; future prices are unconstrained.':'Statistical bands can exclude extreme cycle peaks.'}`;}
function cpiFactor(t){const key=new Date(t).toISOString().slice(0,7),keys=Object.keys(data.cpi).sort(),last=keys.at(-1);let cpi=data.cpi[key];if(!cpi){const prior=keys.filter(k=>k<=key).at(-1)||keys[0];cpi=data.cpi[prior];}return data.cpi[last]/cpi;}
function shownValue(v,t){return state.real?v*cpiFactor(t):v;}
function spark(id,vals,color){let lo=Math.min(...vals),hi=Math.max(...vals),span=hi-lo||1;const path=vals.map((v,i)=>`${i?'L':'M'}${(i/(vals.length-1)*120).toFixed(1)},${(26-(v-lo)/span*24).toFixed(1)}`).join(' ');$(id).innerHTML=`<path d="${path}" fill="none" stroke="${color}" stroke-width="1.7"/>`;}
function renderMetrics(){const last=points.at(-1),spot=quote?.price||last.p,t=quote?.time||last.t,trend=model.price(t),ratio=spot/trend;$('price-value').textContent=money(spot);$('trend-value').textContent=money(trend);$('ratio-value').textContent=ratio.toFixed(2)+'×';$('ratio-note').textContent=quote?'Spot relative to fitted trend':'At last daily close';$('ratio-marker').style.left=Math.min(98,Math.max(2,Math.log2(ratio)*30+50))+'%';const live=window.netSupply?.(),supply=live?.supply||data.snapshot.supply;$('supply-value').textContent=(supply/1e6).toFixed(3)+'M';$('supply-note').textContent=(supply/21e6*100).toFixed(2)+'% of 21 million · '+(live?'block '+live.height.toLocaleString():'snapshot');spark('price-spark',points.slice(-90).filter((_,i)=>i%3===0).map(p=>p.p),'#83d5a3');spark('trend-spark',points.slice(-365).filter((_,i)=>i%12===0).map(p=>model.price(p.t)),'#6c97de');$('exponent').textContent=model.b.toFixed(2);$('exponent-stat').textContent=model.b.toFixed(3);$('coefficient').textContent=(10**model.a).toExponential(2);$('r2-stat').textContent=(model.r2*100).toFixed(2)+'%';$('observations').textContent=points.length.toLocaleString();const current=Date.now()-last.t<2.5*day,cpiMonth=new Date(Object.keys(data.cpi).sort().at(-1)+'-01T00:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});$('data-freshness').textContent=(current?'Up to date · daily history through ':'Daily history through ')+dateLabel(last.t)+' · CPI through '+cpiMonth+' · Price, candles and network data refresh live every minute.';$('data-freshness').classList.toggle('fresh',current);$('history-note').textContent='Coin Metrics + Coinbase · Daily · Through '+dateLabel(last.t);$('data-detail').textContent=`Historical prices: ${dateLabel(points[0].t)} – ${dateLabel(last.t)}. Supply snapshot: ${dateLabel(last.t)}.`;const cpiDate=Object.keys(data.cpi).sort().at(-1);$('cpi-detail').textContent=`U.S. CPI-U, all items, not seasonally adjusted (BLS series CUUR0000SA0). Prices are expressed in ${new Date(cpiDate+'-01T00:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})} dollars. Daily price × latest CPI ÷ price-month CPI. Missing CPI months use the latest available prior month. The latest available CPI is held constant after ${cpiDate}.`;updateProjection();window.renderSignal?.();}
function updateProjection(){if(!model)return;const t=Date.UTC(state.year,0,1);$('horizon-label').textContent=state.year;$('projection-year').textContent=state.year;$('projection-price').textContent=money(model.price(t));$('horizon').style.background=`linear-gradient(90deg,#6c97de ${(state.year-2027)/13*100}%,#303844 ${(state.year-2027)/13*100}%)`;}
function textSVG(x,y,s,anchor='start',color='#697688',size=9){return `<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-family="IBM Plex Mono,monospace" font-size="${window.innerWidth<720?size*1.5:size}">${s}</text>`;}
function mainLimits(){return {from:points[0].t,to:state.view==='power'?Math.max(points.at(-1).t,Date.UTC(state.year,0,1)):points.at(-1).t}}
function mainDomain(){const limits=mainLimits();if(mainView.from!==null&&mainView.to!==null&&mainView.from<limits.to){return {from:Math.max(limits.from,mainView.from),to:Math.min(limits.to,mainView.to)}}return {from:state.range==='all'?limits.from:Math.max(limits.from,points.at(-1).t-Number(state.range)*365.25*day),to:limits.to}}
function setMainViewport(from,to){if(!points.length)return;const limits=mainLimits(),span=Math.min(limits.to-limits.from,Math.max(7*day,to-from));from=Math.max(limits.from,Math.min(from,limits.to-span));mainView.from=from;mainView.to=from+span;drawMain()}
function resetMainViewport(){mainView.from=null;mainView.to=null;hideTooltip();drawMain()}
function mainPointAt(t){if(t>points.at(-1).t+day/2)return {t:Math.min(mainLimits().to,Math.max(mainLimits().from,Math.round(t/day)*day)),p:null,dd:null};let lo=0,hi=points.length-1;while(lo<hi){const mid=Math.floor((lo+hi)/2);if(points[mid].t<t)lo=mid+1;else hi=mid;}if(lo>0&&Math.abs(points[lo-1].t-t)<Math.abs(points[lo].t-t))lo--;return points[lo]}
function mainPinSVG(x,y,minT,maxT,cycles,top,ph){const p=mainView.selected;if(!p||p.t<minT||p.t>maxT)return '';const xx=x(p.t),value=cycles?p.dd:shownValue(p.p??model.price(p.t),p.t);let out=`<g id="main-pinned-marker"><line x1="${xx}" x2="${xx}" y1="${top}" y2="${top+ph}" stroke="#f6a13b" stroke-dasharray="4 4" opacity=".7"/><circle cx="${xx}" cy="${y(value)}" r="5" fill="#111419" stroke="#f6a13b" stroke-width="2"/>`;if(!cycles&&state.showBands)out+=`<circle cx="${xx}" cy="${y(shownValue(bandValue(p.t,true),p.t))}" r="4" fill="#9b82d5"/><circle cx="${xx}" cy="${y(shownValue(bandValue(p.t,false),p.t))}" r="4" fill="#6c97de"/>`;return out+'</g>'}
function updateMainInspector(){const p=mainView.selected;$('main-inspector').hidden=!p;if(!p)return;const cycles=state.view==='cycles';$('main-selected-date').textContent=dateLabel(p.t)+(p.p===null?' · model only':'');$('main-price-label').textContent=cycles?'Drawdown':'Bitcoin price';$('main-selected-price').textContent=cycles?p.dd.toFixed(2)+'%':p.p===null?'No observation':money(shownValue(p.p,p.t));$('main-selected-trend').textContent=money(shownValue(model.price(p.t),p.t));$('main-selected-upper').textContent=money(shownValue(bandValue(p.t,true),p.t));$('main-selected-lower').textContent=money(shownValue(bandValue(p.t,false),p.t));$('main-selected-ratio').textContent=p.p===null?'—':(p.p/model.price(p.t)).toFixed(2)+'×';[...$('main-inspector').querySelectorAll('.inspector-values>div')].forEach((node,i)=>node.hidden=cycles&&i>0)}
function drawMain(){if(!points.length)return;const cycles=state.view==='cycles',end=points.at(-1).t,{from:minT,to:maxT}=mainDomain(),visible=points.filter(p=>p.t>=minT&&p.t<=maxT),curve=Array.from({length:240},(_,i)=>({t:minT+(maxT-minT)*i/239}));
const mobile=window.innerWidth<720,W=mobile?440:1100,H=mobile?330:355,left=8,right=mobile?84:87,top=24,bottom=mobile?42:35,pw=W-left-right,ph=H-top-bottom;
let lo,hi;const isLog=state.scale==='log'&&!cycles,values=[];
for(const p of visible){if(state.showPrice||cycles)values.push(cycles?p.dd:shownValue(p.p,p.t));if(!cycles&&state.showTrend)values.push(shownValue(model.price(p.t),p.t));if(!cycles&&state.showBands)values.push(shownValue(bandValue(p.t,false),p.t),shownValue(bandValue(p.t,true),p.t));}
for(const p of curve){if(!cycles&&state.showTrend)values.push(shownValue(model.price(p.t),p.t));if(!cycles&&state.showBands)values.push(shownValue(bandValue(p.t,true),p.t),shownValue(bandValue(p.t,false),p.t));}
if(!values.length)values.push(shownValue(model.price(minT),minT),shownValue(model.price(maxT),maxT));
if(!values.length)values.push(...visible.map(p=>shownValue(p.p,p.t)));
if(cycles){lo=-100;hi=0;}else if(isLog){lo=Math.log10(Math.min(...values))-.16;hi=Math.log10(Math.max(...values))+.13;}else{lo=0;hi=Math.max(...values)*1.1;}
const x=t=>left+(t-minT)/(maxT-minT)*pw,y=v=>top+(hi-(isLog?Math.log10(Math.max(v,1e-8)):v))/(hi-lo)*ph;
let out=`<defs><linearGradient id="price-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f6a13b" stop-opacity=".12"/><stop offset="1" stop-color="#f6a13b" stop-opacity="0"/></linearGradient><linearGradient id="band-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9b82d5" stop-opacity=".14"/><stop offset="1" stop-color="#6c97de" stop-opacity=".06"/></linearGradient><clipPath id="plot-clip"><rect x="${left}" y="${top}" width="${pw}" height="${ph}"/></clipPath></defs>`;
let ticks=[];if(cycles)ticks=[0,-25,-50,-75,-100];else if(isLog){if(hi-lo<1.2){for(let i=0;i<5;i++)ticks.push(10**(lo+(hi-lo)*i/4));}else{const step=Math.max(1,Math.ceil((hi-lo)/6));for(let p=Math.ceil(lo);p<=hi;p+=step)ticks.push(10**p);}}else for(let i=0;i<6;i++)ticks.push(hi*i/5);
const tagP=visible.length&&(state.showPrice||cycles)?visible.at(-1):null,tagY=tagP?y(cycles?tagP.dd:shownValue(tagP.p,tagP.t)):-1e9;for(const v of ticks){const yy=y(v);out+=`<line x1="${left}" y1="${yy}" x2="${left+pw}" y2="${yy}" stroke="#28303b" stroke-dasharray="3 5" opacity=".62"/>`+(Math.abs(yy-tagY)<(mobile?24:18)?'':textSVG(W-right+13,yy+3,cycles?v+'%':compact(v)));}
const firstYear=new Date(minT).getUTCFullYear(),lastYear=new Date(maxT).getUTCFullYear(),step=Math.max(1,Math.ceil((lastYear-firstYear)/6));if(lastYear-firstYear<=1){for(let i=0;i<=4;i++){const t=minT+(maxT-minT)*i/4;out+=textSVG(x(t),H-(mobile?14:11),new Date(t).toLocaleDateString('en-US',{month:'short',year:'2-digit',timeZone:'UTC'}),i===0?'start':i===4?'end':'middle');}}else{for(let year=firstYear+1;year<=lastYear;year+=step){const xx=x(Date.UTC(year,0,1));out+=`<line x1="${xx}" y1="${top}" x2="${xx}" y2="${top+ph}" stroke="#242c37" opacity=".45"/>`+textSVG(xx,H-(mobile?14:11),year,'middle');}}
const sampled=visible.filter((_,i)=>i%Math.max(1,Math.floor(visible.length/1200))===0);if(visible.length&&sampled.at(-1)!==visible.at(-1))sampled.push(visible.at(-1));
const pathFor=(arr,val)=>arr.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(2)},${y(val(p)).toFixed(2)}`).join(' ');
out+='<g clip-path="url(#plot-clip)">';
if(!cycles){if(state.showBands){const upper=pathFor(curve,p=>shownValue(bandValue(p.t,true),p.t));const lower=pathFor([...curve].reverse(),p=>shownValue(bandValue(p.t,false),p.t));out+=`<path d="${upper} ${lower.replace(/^M/,'L')} Z" fill="url(#band-fill)"/><path d="${upper}" fill="none" stroke="#9b82d5" stroke-width="1" stroke-opacity=".47"/><path d="${lower}" fill="none" stroke="#6c97de" stroke-width="1" stroke-opacity=".5"/>`;}
if(state.showTrend)out+=`<path d="${pathFor(curve,p=>shownValue(model.price(p.t),p.t))}" fill="none" stroke="#9babc2" stroke-width="1.3" stroke-dasharray="5 5" opacity=".8"/>`;if(state.view==='power'&&end>=minT&&end<=maxT){const xx=x(end);out+=`<line x1="${xx}" y1="${top}" x2="${xx}" y2="${top+ph}" stroke="#606b7a" stroke-dasharray="3 5"/>`+(xx>left+pw*.72?textSVG(xx-9,top+12,'← HISTORY · MODEL →','end','#7787a0',8):textSVG(xx+9,top+12,'EXTRAPOLATION →','start','#7787a0',8));}}
if(visible.length&&(state.showPrice||cycles)){const line=pathFor(sampled,p=>cycles?p.dd:shownValue(p.p,p.t));const base=cycles?y(0):top+ph;out+=`<path d="${line} L${x(sampled.at(-1).t)},${base} L${x(sampled[0].t)},${base} Z" fill="url(#price-fill)"/><path d="${line}" fill="none" stroke="#f6a13b" stroke-width="${cycles?1.5:1.7}" stroke-linejoin="round" stroke-linecap="round"/>`;}
out+='</g>';if(visible.length&&(state.showPrice||cycles)){const p=visible.at(-1),v=cycles?p.dd:shownValue(p.p,p.t),yy=y(v),xx=x(p.t);out+=`<circle cx="${xx}" cy="${yy}" r="3.2" fill="#f6a13b" stroke="#15191f" stroke-width="2"/><line x1="${xx}" y1="${yy}" x2="${W-right+6}" y2="${yy}" stroke="#f6a13b" stroke-dasharray="3 4" opacity=".35"/><rect x="${W-right+6}" y="${yy-(mobile?14:10)}" width="${right-11}" height="${mobile?28:20}" rx="3" fill="#f6a13b"/>`+textSVG(W-right+(right-5)/2,yy+(mobile?5:3),cycles?v.toFixed(1)+'%':compact(v),'middle','#18191c',9);}
out+=mainPinSVG(x,y,minT,maxT,cycles,top,ph);out+=`<g id="hover-marker" style="display:none"><line id="hover-line" y1="${top}" y2="${top+ph}" stroke="#707b8e" stroke-dasharray="3 4"/><circle id="hover-dot" r="4" fill="#f6a13b" stroke="#15191f" stroke-width="2"/><circle id="hover-upper" r="3.5" fill="#9b82d5"/><circle id="hover-lower" r="3.5" fill="#6c97de"/></g>`;
document.querySelectorAll('[data-range]').forEach(button=>{const active=mainView.from===null&&button.dataset.range===state.range;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',active)});$('main-chart').setAttribute('viewBox',`0 0 ${W} ${H}`);$('main-chart').innerHTML=out;chartMeta={x,y,minT,maxT,visible,W,H,left,pw,cycles,top,ph};updateMainInspector();$('main-chart').setAttribute('aria-label',`Bitcoin chart, ${dateLabel(minT)} to ${dateLabel(maxT)}. ${visible.length} daily prices. Scroll or pinch to zoom, drag to pan, click to pin. Plus/minus zoom, arrow keys pan, Enter selects, Escape clears.`);$('axis-label').textContent=cycles?'% from prior daily high':`${state.real?'CPI-adjusted USD':'USD'} · ${state.scale==='log'?'logarithmic':'linear'} scale`;
}
function drawMini(){const last=points.at(-1),ath=points.reduce((a,p)=>p.p>a.p?p:a,points[0]);$('drawdown').textContent=last.dd.toFixed(2)+'%';$('ath-price').textContent=money(ath.p);$('ath-date').textContent=dateLabel(ath.t);const W=510,H=174,left=0,right=37,top=8,ph=137,x=t=>left+(t-points[0].t)/(last.t-points[0].t)*(W-right),y=v=>top-v/100*ph;let out='<defs><linearGradient id="dd-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#f6a13b" stop-opacity=".02"/><stop offset="1" stop-color="#f6a13b" stop-opacity=".12"/></linearGradient></defs>';for(const v of [0,-50,-100])out+=`<line x1="0" x2="${W-right}" y1="${y(v)}" y2="${y(v)}" stroke="#28303b" stroke-dasharray="3 5"/>`+textSVG(W-right+8,y(v)+3,v+'%','start','#637185',8);const sampled=points.filter((_,i)=>i%8===0),path=sampled.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(1)},${y(p.dd).toFixed(1)}`).join(' ');out+=`<path d="${path} L${x(sampled.at(-1).t)},${top} L0,${top} Z" fill="url(#dd-fill)"/><path d="${path}" fill="none" stroke="#c89365" stroke-width="1.15" opacity=".88"/>`;for(const year of [2012,2016,2020,2024])out+=textSVG(x(Date.UTC(year,0,1)),H-8,year,'middle','#637185',8);$('mini-chart').innerHTML=out;}
function render(){renderMetrics();drawMain();drawMini();$('chart-loading').hidden=true;}
const VIEWS=['overview','spot','power','adjusted','cycles','signal','mempool','mining','supply','lightning','learn'];
const MARKET_VIEWS=['overview','power','adjusted','cycles'];
const VIEW_COPY={
 overview:['See the bigger picture','Bitcoin, beyond the daily noise. Price, network and long-term trajectory in one place.','Overview'],
 spot:['The market, in motion','Track Bitcoin spot prices with interactive intraday and long-term market candles.','Spot price'],
 power:['Time is the bigger picture','Explore a historical fit, and what its trajectory looks like over time.','Power law'],
 adjusted:['Price, with perspective','Look beyond nominal dollars. See Bitcoin through the lens of purchasing power.','Adjusted price'],
 signal:['When to buy, by the numbers','A transparent valuation score built from Bitcoin’s own history, with the evidence behind it.','Buy signal'],
 cycles:['The journey isn’t a straight line','Explore the drawdowns behind Bitcoin’s long-term ascent.','Market cycles'],
 mempool:['The waiting room','Every unconfirmed transaction, the fees it bids, and the blocks it is lining up for.','Mempool & fees'],
 mining:['Proof of work, live','The computing power securing Bitcoin, who is finding blocks, and when difficulty changes next.','Blocks & mining'],
 supply:['Scarcity, by schedule','21 million coins, released on a fixed timetable that halves about every four years.','Supply & halving'],
 lightning:['Payments at light speed','The second layer built for instant, low-cost Bitcoin payments.','Lightning'],
 learn:['Bitcoin, explained','The key ideas in plain language, with a converter and glossary to keep handy.','Bitcoin 101']};
const CHART_COPY={overview:['Bitcoin & the power law','Daily price against Bitcoin’s modeled growth trajectory.'],power:['Bitcoin’s long-term power law','Daily prices inside a peak-calibrated historical envelope, plus extrapolation.'],adjusted:['Bitcoin in constant dollars','Daily prices and the fitted trend adjusted using monthly U.S. CPI.'],cycles:['Bitcoin market drawdowns','Distance from the highest daily price observed up to each date.']};
function setView(view){if(!VIEWS.includes(view))view='overview';state.view=view;mainView.from=null;mainView.to=null;mainView.selected=null;mainView.hovered=null;hideTooltip();
 const [title,sub,crumb]=VIEW_COPY[view];$('page-title').innerHTML=title+'<span>.</span>';$('page-subtitle').textContent=sub;$('breadcrumb').textContent=crumb;$('page-eyebrow').textContent=view==='learn'?'LEARN':MARKET_VIEWS.includes(view)||view==='spot'||view==='signal'?'THE LONG VIEW':'LIVE NETWORK';document.title=(view==='overview'?'Bitcoin Observatory · See the bigger picture':crumb+' · Bitcoin Observatory');
 if(CHART_COPY[view]){$('chart-title').textContent=CHART_COPY[view][0];$('chart-subtitle').textContent=CHART_COPY[view][1];}
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 document.querySelectorAll('[data-views]').forEach(el=>el.hidden=!el.dataset.views.split(' ').includes(view));
 state.real=view==='adjusted';$('adjustment').value=state.real?'real':'nominal';$('adjustment').disabled=view==='cycles';document.querySelector('.scale-controls').style.opacity=view==='cycles'?'.35':'1';document.querySelectorAll('[data-scale]').forEach(b=>b.disabled=view==='cycles');document.querySelectorAll('.chart-legend label').forEach(l=>l.hidden=view==='cycles');
 const tabbed=['overview','spot','mempool','mining'].includes(view);$('more-tab').classList.toggle('active',!tabbed);if(!tabbed)$('more-tab').setAttribute('aria-current','page');else $('more-tab').removeAttribute('aria-current');$('more-sheet').open&&$('more-sheet').close();
 window.redrawSpot?.();window.onNetworkView?.(view);window.renderSignal?.();if(model&&MARKET_VIEWS.includes(view))drawMain();if(location.hash!=='#'+view)history.pushState(null,'','#'+view);}
function notify(msg){$('toast').textContent=msg;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,4200);}
async function updateQuote(manual=false){if(refreshing)return;refreshing=true;$('refresh').querySelector('i').classList.add('spin');try{let price,source='Coinbase Exchange';try{const r=await fetch('https://api.exchange.coinbase.com/products/BTC-USD/ticker',{signal:AbortSignal.timeout(12000),cache:'no-store'});if(!r.ok)throw Error('Ticker unavailable');price=Number((await r.json()).price);}catch{const r=await fetch('https://api.coinbase.com/v2/prices/BTC-USD/spot',{signal:AbortSignal.timeout(12000),cache:'no-store'});if(!r.ok)throw Error('Quote unavailable');price=Number((await r.json()).data.amount);source='Coinbase';}if(!Number.isFinite(price)||price<=0)throw Error('Invalid price');quote={price,time:Date.now(),source};try{localStorage.setItem('observatory-quote',JSON.stringify(quote))}catch{}$('quote-status').textContent='Live spot · '+source;$('price-note').textContent='Updated '+new Date(quote.time).toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'})+' UTC';$('price-note').className='green';document.querySelector('.market-bar .status-dot').classList.remove('stale-dot');renderMetrics();window.onSpotQuote?.(quote,true);if(manual)notify('Live data refreshed · daily history through '+dateLabel(points.at(-1).t)+'.');}catch{let cached;try{cached=JSON.parse(localStorage.getItem('observatory-quote'))}catch{}if(cached&&Number.isFinite(cached.price)&&Number.isFinite(cached.time)&&cached.price>0&&cached.time<=Date.now()&&cached.time>Date.now()-day){quote=cached;$('quote-status').textContent='Cached quote · '+dateLabel(cached.time);$('price-note').textContent='Cached '+new Date(cached.time).toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'})+' UTC';}else{quote=null;$('quote-status').textContent='Historical snapshot · '+dateLabel(points.at(-1).t);$('price-note').textContent='Daily close · '+dateLabel(points.at(-1).t);} $('price-note').className='muted';document.querySelector('.market-bar .status-dot').classList.add('stale-dot');renderMetrics();window.onSpotQuote?.(quote,false);if(manual)notify('Live quote unavailable. Showing the latest available snapshot.');}finally{refreshing=false;$('refresh').querySelector('i').classList.remove('spin');}}
function exportFile(name,contents,type){const blob=new Blob([contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){if(!model)return;const rows=['date,price_usd,power_law_usd,cpi_adjusted_usd,drawdown_pct'];for(const p of points)rows.push([p.d,p.p,model.price(p.t).toFixed(5),(p.p*cpiFactor(p.t)).toFixed(5),p.dd.toFixed(5)].join(','));exportFile('bitcoin-observatory-history.csv',rows.join('\n'),'text/csv');notify('Historical data exported as CSV.');}
function exportChart(){if(!model)return;const svg=$('main-chart').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.querySelector('#hover-marker')?.remove();svg.querySelector('#main-pinned-marker')?.remove();const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','100%');bg.setAttribute('height','100%');bg.setAttribute('fill','#111419');svg.prepend(bg);const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=$('chart-title').textContent+' · daily history through '+points.at(-1).d;svg.prepend(title);exportFile('bitcoin-observatory-chart.svg',new XMLSerializer().serializeToString(svg),'image/svg+xml');notify('Chart exported as SVG.');}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{setView(b.dataset.view);window.scrollTo({top:0,behavior:'smooth'})}));
document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{state.range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});mainView.from=null;mainView.to=null;hideTooltip();drawMain()}));
document.querySelectorAll('[data-scale]').forEach(b=>b.addEventListener('click',()=>{state.scale=b.dataset.scale;document.querySelectorAll('[data-scale]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});drawMain()}));
window.addEventListener('popstate',()=>setView(location.hash.slice(1)));window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==state.view)setView(location.hash.slice(1))});
$('adjustment').addEventListener('change',()=>{state.real=$('adjustment').value==='real';drawMain()});
for(const [id,key] of [['show-price','showPrice'],['show-trend','showTrend'],['show-bands','showBands']])$(id).addEventListener('change',()=>{state[key]=$(id).checked;drawMain()});
$('horizon').addEventListener('input',()=>{state.year=Number($('horizon').value);updateProjection();if(state.view==='power'){mainView.from=null;mainView.to=null;drawMain()}});
$('band-width').addEventListener('change',()=>{state.bandMode=$('band-width').value==='envelope'?'envelope':'sigma';state.band=Number($('band-width').value)||1;document.querySelector('label:has(#show-bands)').lastChild.textContent=state.bandMode==='envelope'?'Historical envelope':`± ${state.band}σ bands`;updateCoverage();drawMain()});
for(const id of ['method-side','method-nav','help','sources'])$(id).addEventListener('click',()=>$('method-dialog').showModal());
$('close-dialog').addEventListener('click',()=>$('method-dialog').close());$('method-dialog').addEventListener('click',e=>{if(e.target===$('method-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('export-side').addEventListener('click',exportData);$('more-tab').addEventListener('click',()=>$('more-sheet').showModal());$('more-close').addEventListener('click',()=>$('more-sheet').close());$('more-sheet').addEventListener('click',e=>{if(e.target===$('more-sheet'))$('more-sheet').close()});$('more-method').addEventListener('click',()=>{$('more-sheet').close();$('method-dialog').showModal()});$('more-export').addEventListener('click',()=>{$('more-sheet').close();exportData()});$('export-chart').addEventListener('click',exportChart);$('refresh').addEventListener('click',()=>{updateQuote(true);window.refreshSpot?.();window.refreshNetwork?.(true)});
$('adjusted-view').addEventListener('click',()=>{setView('adjusted');$('main-panel').scrollIntoView({behavior:'smooth',block:'start'})});$('cycle-view').addEventListener('click',()=>{setView('cycles');$('main-panel').scrollIntoView({behavior:'smooth',block:'start'})});
function mainEventPoint(event){if(!chartMeta)return null;if(!event)return mainView.hovered&&mainView.hovered.t>=chartMeta.minT&&mainView.hovered.t<=chartMeta.maxT?mainView.hovered:mainPointAt((chartMeta.minT+chartMeta.maxT)/2);const rect=$('main-chart').getBoundingClientRect();if(!rect.width)return null;const xx=(event.clientX-rect.left)/rect.width*chartMeta.W;if(xx<chartMeta.left||xx>chartMeta.left+chartMeta.pw)return null;return mainPointAt(chartMeta.minT+(xx-chartMeta.left)/chartMeta.pw*(chartMeta.maxT-chartMeta.minT))}
function showMainTooltip(event){const p=mainEventPoint(event);if(!p){hideTooltip();return;}mainView.hovered=p;const {x,y,minT,maxT,W,H,cycles}=chartMeta,rect=$('main-chart').getBoundingClientRect(),value=cycles?p.dd:shownValue(p.p??model.price(p.t),p.t),cx=x(p.t),cy=y(value);$('hover-marker').style.display='';$('hover-line').setAttribute('x1',cx);$('hover-line').setAttribute('x2',cx);$('hover-dot').setAttribute('cx',cx);$('hover-dot').setAttribute('cy',cy);for(const [id,upper] of [['hover-upper',true],['hover-lower',false]]){$(id).style.display=cycles||!state.showBands?'none':'';$(id).setAttribute('cx',cx);$(id).setAttribute('cy',y(shownValue(bandValue(p.t,upper),p.t)));}const tooltip=$('chart-tooltip');tooltip.innerHTML=`<strong>${dateLabel(p.t)}${p.p===null?' · MODEL ONLY':''}</strong><p>${cycles?'Drawdown':'Bitcoin'}<b>${cycles?p.dd.toFixed(2)+'%':p.p===null?'No observation':money(shownValue(p.p,p.t))}</b></p>${cycles?'':`<p>Fitted trend<b>${money(shownValue(model.price(p.t),p.t))}</b></p><p class="upper-label">Upper bound<b>${money(shownValue(bandValue(p.t,true),p.t))}</b></p><p class="lower-label">Lower bound<b>${money(shownValue(bandValue(p.t,false),p.t))}</b></p><p>Price / trend<b>${p.p===null?'—':(p.p/model.price(p.t)).toFixed(2)+'×'}</b></p>`}`;tooltip.hidden=false;const container=$('chart-container').getBoundingClientRect();tooltip.style.left=Math.min(Math.max(8,event.clientX-container.left+15),Math.max(8,container.width-tooltip.offsetWidth-8))+'px';tooltip.style.top=Math.min(Math.max(4,cy/H*rect.height-35),Math.max(4,container.height-tooltip.offsetHeight-8))+'px'}
function hideTooltip(){$('chart-tooltip').hidden=true;const marker=$('hover-marker');if(marker)marker.style.display='none'}
function clearMainSelection(){mainView.selected=null;mainView.hovered=null;hideTooltip();drawMain()}
function selectMainPoint(event){const p=mainEventPoint(event);if(!p)return;mainView.selected={...p};hideTooltip();drawMain()}
const mainGestures=bindChartGestures($('main-chart'),{getView:()=>points.length?mainDomain():{from:0,to:0},getMeta:()=>chartMeta,setView:setMainViewport,onHover:showMainTooltip,onLeave:hideTooltip,onSelect:selectMainPoint,onClear:clearMainSelection,onReset:resetMainViewport});
$('main-zoom-in').addEventListener('click',()=>mainGestures.zoom(.7));$('main-zoom-out').addEventListener('click',()=>mainGestures.zoom(1.4));$('main-reset').addEventListener('click',resetMainViewport);$('main-clear-selection').addEventListener('click',clearMainSelection);
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{drawMain();hideTooltip()},100)});
function clock(){$('utc-time').textContent=new Date().toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'})+' UTC'}clock();setInterval(clock,30000);
setView(location.hash.slice(1)||state.view);
/* Self-healing history: if data.json is behind (e.g. the daily update job hasn't run), append
   Coinbase daily closes for every completed UTC day since, so the long-term chart is always current. */
async function extendHistory(){const lastDay=Date.parse(data.prices.at(-1)[0]+'T00:00:00Z'),today=Math.floor(Date.now()/day)*day;if(today-lastDay<2*day)return 0;const closes=new Map();for(let from=lastDay+day;from<today;from+=290*day){const to=Math.min(today,from+290*day),q=new URLSearchParams({granularity:86400,start:new Date(from).toISOString(),end:new Date(to).toISOString()}),r=await fetch('https://api.exchange.coinbase.com/products/BTC-USD/candles?'+q,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Daily candles unavailable');for(const row of await r.json()){const t=row[0]*1000,close=Number(row[4]);if(t>lastDay&&t<today&&close>0)closes.set(t,close)}}const added=[...closes].sort((a,b)=>a[0]-b[0]).map(([t,c])=>[new Date(t).toISOString().slice(0,10),c]);data.prices.push(...added);return added.length}
fetch('data.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('History not available');return r.json()}).then(d=>{data=d;hydrate();extendHistory().then(n=>{if(n){hydrate();}}).catch(()=>{});if(MARKET_VIEWS.includes(state.view))drawMain();updateQuote();setInterval(()=>{if(!document.hidden)updateQuote()},60000);document.addEventListener('visibilitychange',()=>{if(document.hidden)return;clock();if(!quote||Date.now()-quote.time>60000){updateQuote();window.refreshSpot?.();window.refreshNetwork?.(false)}})}).catch(()=>{$('chart-loading').textContent='Could not load history. Refresh the page to retry.';$('quote-status').textContent='Historical data unavailable';notify('Historical data could not be loaded. Please reload.');});
